1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.security.NoSuchAlgorithmException;
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Locale;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName",
26	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "initials",
28	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
29	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
30	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
33	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
34	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
35	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
36	    @Mapping(target = "locality", expression = "java(locality(owner))")
37	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
38	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
39	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * Derives an owner's age band from its birth date, computed as the owner's age on its
44	     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
45	     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
46	     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
47	     * response.
48	     *
49	     * @param owner the owner to derive the age band for
50	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
51	     *     is held
52	     */
53	    default String ageBand(Owner owner) {
54	        java.time.LocalDate birthDate = owner.getBirthDate();
55	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
56	        if (birthDate == null || registrationDate == null) {
57	            return null;
58	        }
59	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
60	        if (age < 18) {
61	            return "MINOR";
62	        }
63	        return age < 65 ? "ADULT" : "SENIOR";
64	    }
65	
66	    /**
67	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
68	     * email, otherwise {@code "PHONE"}.
69	     *
70	     * @param owner the owner to derive the contact preference for
71	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
72	     */
73	    default String contactPreference(Owner owner) {
74	        String email = owner.getEmail();
75	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
76	    }
77	
78	    /**
79	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
80	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
81	     * normalizing telephones into E.164 form.
82	     */
83	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
84	
85	    /**
86	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
87	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
88	     * The country code is taken as the longest recognized prefix (see
89	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
90	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
91	     * is returned unchanged.
92	     *
93	     * @param owner the owner to format the telephone display for
94	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
95	     *     digit string
96	     */
97	    default String telephoneDisplay(Owner owner) {
98	        String telephone = owner.getTelephone();
99	        if (telephone == null || !telephone.startsWith("+")) {
100	            return telephone;
101	        }
102	        String digits = telephone.substring(1);
103	        if (!digits.matches("[0-9]+")) {
104	            return telephone;
105	        }
106	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
107	            .filter(digits::startsWith)
108	            .max(java.util.Comparator.comparingInt(String::length))
109	            .orElseGet(() -> digits.substring(0, 1));
110	        String national = digits.substring(countryCode.length());
111	        StringBuilder sb = new StringBuilder("+").append(countryCode);
112	        for (int i = 0; i < national.length(); i += 3) {
113	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
114	        }
115	        return sb.toString();
116	    }
117	
118	    /**
119	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
120	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
121	     * the customer code's region is itself derived from the postcode (falling back to the city), the
122	     * locality now moves with the identity rather than being computed independently. The result is
123	     * {@code "UNKNOWN"} when no customer code is present.
124	     *
125	     * @param owner the owner to derive the locality for
126	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
127	     */
128	    default String locality(Owner owner) {
129	        String code = owner.getCustomerCode();
130	        if (code == null || code.isEmpty()) {
131	            return "UNKNOWN";
132	        }
133	        int dash = code.indexOf('-');
134	        return dash < 0 ? code : code.substring(0, dash);
135	    }
136	
137	    /**
138	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
139	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
140	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
141	     * than {@code 365} days - the number of days between the owner's registration date and the
142	     * current server date. Because a newly created owner registers on the current date, its tenure
143	     * is zero, so a new owner never earns the tenure points.
144	     *
145	     * @param owner the owner to derive the membership points for
146	     * @return the membership points, {@code 0} or more
147	     */
148	    default Integer membershipPoints(Owner owner) {
149	        int points = 0;
150	        String email = owner.getEmail();
151	        if (email != null && !email.isBlank()) {
152	            points += 2;
153	        }
154	        Integer namesakeCount = owner.getNamesakeCount();
155	        if (namesakeCount != null && namesakeCount == 0) {
156	            points += 1;
157	        }
158	        Integer householdMemberCount = owner.getHouseholdMemberCount();
159	        if (householdMemberCount != null && householdMemberCount >= 3) {
160	            points += 2;
161	        }
162	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
163	        long tenureDays = registrationDate == null ? 0
164	            : java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
165	        if (tenureDays > 365) {
166	            points += 3;
167	        }
168	        return points;
169	    }
170	
171	    /**
172	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
173	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
174	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more.
175	     *
176	     * @param owner the owner to derive the membership level for
177	     * @return the membership level, between {@code 1} and {@code 4}
178	     */
179	    default Integer membershipLevel(Owner owner) {
180	        int points = membershipPoints(owner);
181	        if (points <= 1) {
182	            return 1;
183	        }
184	        if (points <= 3) {
185	            return 2;
186	        }
187	        if (points <= 5) {
188	            return 3;
189	        }
190	        return 4;
191	    }
192	
193	    /**
194	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
195	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
196	     * two digits (zero-padded) of the owner's registration date year (e.g. {@code NSW-1A2B3C4D-M26}).
197	     *
198	     * @param owner the owner to derive the membership number for
199	     * @return the formatted membership number
200	     */
201	    default String membershipNumber(Owner owner) {
202	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
203	        return owner.getCustomerCode() + "-M" + yy;
204	    }
205	
206	    /**
207	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
208	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
209	     * are ignored.
210	     *
211	     * @param owner the owner to derive the check digit for
212	     * @return the Luhn check digit, between {@code 0} and {@code 9}
213	     */
214	    default Integer checkDigit(Owner owner) {
215	        String code = owner.getCustomerCode();
216	        int sum = 0;
217	        boolean dbl = true;
218	        for (int i = code.length() - 1; i >= 0; i--) {
219	            char c = code.charAt(i);
220	            if (c < '0' || c > '9') {
221	                continue;
222	            }
223	            int d = c - '0';
224	            if (dbl) {
225	                d *= 2;
226	                if (d > 9) {
227	                    d -= 9;
228	                }
229	            }
230	            sum += d;
231	            dbl = !dbl;
232	        }
233	        return (10 - (sum % 10)) % 10;
234	    }
